class PushBoxGame:
    WALL = "#"
    PLAYER = "O"
    TARGET = "G"
    BOX = "X"

    def __init__(self, game_map):
        self._game_map = game_map
        self._player_row = 0
        self._player_col = 0
        self._targets = []
        self._boxes = []
        self._target_count = 0
        self._is_game_over = False

        self._init_game()

    @property
    def map(self):
        return self._game_map

    @map.setter
    def map(self, value):
        self._game_map = value

    @property
    def player_row(self):
        return self._player_row

    @player_row.setter
    def player_row(self, value):
        self._player_row = value

    @property
    def player_col(self):
        return self._player_col

    @player_col.setter
    def player_col(self, value):
        self._player_col = value

    @property
    def targets(self):
        return tuple(self._targets)

    @targets.setter
    def targets(self, value):
        self._targets = list(value)

    @property
    def boxes(self):
        return tuple(self._boxes)

    @boxes.setter
    def boxes(self, value):
        self._boxes = list(value)

    @property
    def target_count(self):
        return self._target_count

    @target_count.setter
    def target_count(self, value):
        self._target_count = value

    @property
    def is_game_over(self):
        return self._is_game_over

    @is_game_over.setter
    def is_game_over(self, value):
        self._is_game_over = value

    def _init_game(self):
        for row in range(len(self._map)):
            for col in range(len(self._map[row])):
                tile = self._map[row][col]
                if tile == self.PLAYER:
                    self._player_row = row
                    self._player_col = col
                elif tile == self.TARGET:
                    self._add_target(row, col)
                elif tile == self.BOX:
                    self._add_box(row, col)

    def _add_target(self, row, col):
        self._targets.append((row, col))
        self._target_count += 1

    def _add_box(self, row, col):
        self._boxes.append((row, col))

    def _box_on_target_count(self):
        return sum(1 for box in self._boxes if box in self._targets)

    def check_win(self):
        if self._box_on_target_count() == self._target_count:
            self._is_game_over = True
        return self._is_game_over

    def _calculate_direction_delta(self, direction):
        if direction == "w":
            return (-1, 0)
        elif direction == "s":
            return (1, 0)
        elif direction == "a":
            return (0, -1)
        elif direction == "d":
            return (0, 1)
        return (0, 0)

    def _is_wall(self, row, col):
        return self._map[row][col] == self.WALL

    def _is_box_at(self, row, col):
        return (row, col) in self._boxes

    def _move_box(self, box_row, box_col, new_box_row, new_box_col):
        self._boxes.remove((box_row, box_col))
        self._boxes.append((new_box_row, new_box_col))

    def _move_player(self, new_player_row, new_player_col):
        self._player_row = new_player_row
        self._player_col = new_player_col

    def _try_push_box(self, new_player_row, new_player_col):
        new_box_row = new_player_row + (new_player_row - self._player_row)
        new_box_col = new_player_col + (new_player_col - self._player_col)

        if not self._is_wall(new_box_row, new_box_col):
            self._move_box(new_player_row, new_player_col, new_box_row, new_box_col)
            self._move_player(new_player_row, new_player_col)
            return True
        return False

    def move(self, direction):
        row_delta, col_delta = self._calculate_direction_delta(direction)
        new_player_row = self._player_row + row_delta
        new_player_col = self._player_col + col_delta

        if self._is_wall(new_player_row, new_player_col):
            return self.check_win()

        if self._is_box_at(new_player_row, new_player_col):
            if not self._try_push_box(new_player_row, new_player_col):
                return self.check_win()
        else:
            self._move_player(new_player_row, new_player_col)

        return self.check_win()
